import {
  Controller,
  Post,
  Body,
  Res,
  UnauthorizedException,
  Get,
  UseGuards,
  Req,
  HttpCode,
  HttpStatus,
} from '@nestjs/common';
import { AdminAuthService } from './admin-auth.service';
import type { Response, Request } from 'express';
import { AdminJwtAuthGuard } from './guards/admin-jwt-auth.guard';
import { AdminJwtRefreshGuard } from './guards/admin-jwt-refresh.guard';
import { ConfigService } from '@nestjs/config';
import {
  ApiTags,
  ApiOperation,
  ApiResponse,
  ApiBody,
  ApiBearerAuth,
} from '@nestjs/swagger';
import { AdminLoginDto } from './dto/admin-login.dto';

@ApiTags('Admin Auth')
@Controller('auth/admin')
export class AdminAuthController {
  constructor(
    private readonly authService: AdminAuthService,
    private configService: ConfigService,
  ) {}

  @Post('login')
  @HttpCode(HttpStatus.OK)
  @ApiOperation({ summary: 'Log in as an admin' })
  @ApiBody({ type: AdminLoginDto })
  @ApiResponse({
    status: 200,
    description: 'Successfully logged in. Sets an HTTP-only cookie.',
  })
  @ApiResponse({ status: 401, description: 'Invalid email or password.' })
  async login(
    @Body() body: AdminLoginDto,
    @Res({ passthrough: true }) res: Response,
  ) {
    const admin = await this.authService.validateAdmin(
      body.email,
      body.password,
    );
    if (!admin) {
      throw new UnauthorizedException('Invalid credentials');
    }
    const {
      access_token,
      refresh_token,
      admin: adminData,
    } = await this.authService.login(admin);

    const isProd = this.configService.get<string>('NODE_ENV') === 'production';

    res.cookie('admin_refresh_token', refresh_token, {
      httpOnly: true,
      secure: isProd,
      sameSite: 'lax',
      path: '/auth/admin',
      maxAge: 7 * 24 * 60 * 60 * 1000, // 7 days
    });

    return {
      message: 'Logged in successfully',
      access_token,
      admin: adminData,
    };
  }

  @Post('logout')
  @HttpCode(HttpStatus.OK)
  @ApiOperation({ summary: 'Log out the current admin' })
  @ApiResponse({
    status: 200,
    description: 'Successfully logged out. Clears the HTTP-only cookie.',
  })
  @UseGuards(AdminJwtAuthGuard)
  logout(@Req() req: Request, @Res({ passthrough: true }) res: Response) {
    const user = req.user as any;
    if (user?.sessionId) {
      this.authService.logout(user.sessionId).catch(console.error);
    }

    res.clearCookie('admin_refresh_token', { path: '/auth/admin' });
    return { message: 'Logged out successfully' };
  }

  @Post('refresh')
  @UseGuards(AdminJwtRefreshGuard)
  @HttpCode(HttpStatus.OK)
  @ApiOperation({ summary: 'Refresh the admin access token' })
  @ApiResponse({
    status: 200,
    description: 'Successfully refreshed token. Sets new HTTP-only cookies.',
  })
  async refresh(
    @Req() req: Request,
    @Res({ passthrough: true }) res: Response,
  ) {
    // We know these exist because the guard passed
    const user = req.user as any;
    const tokens = await this.authService.refreshTokens(
      user.sessionId,
      user.refreshToken,
      user.sub,
    );

    if (!tokens) {
      res.clearCookie('admin_refresh_token', { path: '/auth/admin' });
      throw new UnauthorizedException('Session expired or invalid');
    }

    const isProd = this.configService.get<string>('NODE_ENV') === 'production';

    res.cookie('admin_refresh_token', tokens.refresh_token, {
      httpOnly: true,
      secure: isProd,
      sameSite: 'lax',
      path: '/auth/admin',
      maxAge: 7 * 24 * 60 * 60 * 1000, // 7 days
    });

    return {
      message: 'Tokens refreshed successfully',
      access_token: tokens.access_token,
    };
  }

  @UseGuards(AdminJwtAuthGuard)
  @Get('me')
  @ApiBearerAuth()
  @ApiOperation({ summary: 'Get current admin profile' })
  @ApiResponse({
    status: 200,
    description: 'Returns the currently authenticated admin user.',
  })
  @ApiResponse({ status: 401, description: 'Unauthorized or token expired.' })
  getProfile(@Req() req: Request) {
    return req.user;
  }
}

import { Injectable } from '@nestjs/common';
import { AdminUsersService } from '../users/admin-users.service';
import { JwtService } from '@nestjs/jwt';
import * as bcrypt from 'bcrypt';
import { PrismaService } from '../../shared/prisma/prisma.service';
import { ConfigService } from '@nestjs/config';
import { randomUUID } from 'crypto';

export interface AdminUserPayload {
  id: string;
  email: string;
  role: string;
  [key: string]: unknown;
}

@Injectable()
export class AdminAuthService {
  constructor(
    private adminUsersService: AdminUsersService,
    private jwtService: JwtService,
    private prisma: PrismaService,
    private configService: ConfigService,
  ) {}

  async validateAdmin(
    email: string,
    pass: string,
  ): Promise<AdminUserPayload | null> {
    const admin = await this.adminUsersService.findByEmail(email);
    if (admin && admin.isActive) {
      const isMatch = await bcrypt.compare(pass, admin.passwordHash);
      if (isMatch) {
        // eslint-disable-next-line @typescript-eslint/no-unused-vars
        const { passwordHash, ...result } = admin;
        return result;
      }
    }
    return null;
  }

  async getTokens(
    adminId: string,
    email: string,
    role: string,
    sessionId: string,
  ) {
    const [accessToken, refreshToken] = await Promise.all([
      this.jwtService.signAsync(
        { sub: adminId, email, role, sessionId },
        {
          secret: this.configService.get<string>('JWT_SECRET'),
          expiresIn: '15m',
        },
      ),
      this.jwtService.signAsync(
        { sub: adminId, email, role, sessionId },
        {
          secret: this.configService.get<string>('JWT_REFRESH_SECRET'),
          expiresIn: '7d',
        },
      ),
    ]);

    return {
      accessToken,
      refreshToken,
    };
  }

  async login(admin: AdminUserPayload) {
    // Update lastLogin
    await this.prisma.adminUser.update({
      where: { id: admin.id },
      data: { lastLogin: new Date() },
    });

    const sessionId = randomUUID();
    const tokens = await this.getTokens(
      admin.id,
      admin.email,
      admin.role,
      sessionId,
    );

    // Hash refresh token for storage
    const hashedToken = await bcrypt.hash(tokens.refreshToken, 10);

    // Store session
    const expiresAt = new Date();
    expiresAt.setDate(expiresAt.getDate() + 7); // 7 days

    const session = await this.prisma.adminSession.create({
      data: {
        id: sessionId,
        adminUserId: admin.id,
        hashedToken,
        expiresAt,
      },
    });

    return {
      access_token: tokens.accessToken,
      refresh_token: tokens.refreshToken,
      admin,
    };
  }

  async logout(sessionId: string) {
    await this.prisma.adminSession.deleteMany({
      where: { id: sessionId },
    });
  }

  async refreshTokens(
    sessionId: string,
    refreshToken: string,
    adminId: string,
  ) {
    const session = await this.prisma.adminSession.findUnique({
      where: { id: sessionId },
    });

    if (!session || !session.hashedToken) return null;

    const rtMatches = await bcrypt.compare(refreshToken, session.hashedToken);
    if (!rtMatches) return null;

    const admin = await this.adminUsersService.findById(adminId);
    if (!admin) return null;

    const tokens = await this.getTokens(
      admin.id,
      admin.email,
      admin.role,
      sessionId,
    );
    const newHashedToken = await bcrypt.hash(tokens.refreshToken, 10);

    const expiresAt = new Date();
    expiresAt.setDate(expiresAt.getDate() + 7);

    // Rotate the token by updating the session
    await this.prisma.adminSession.update({
      where: { id: sessionId },
      data: {
        hashedToken: newHashedToken,
        expiresAt,
      },
    });

    return {
      access_token: tokens.accessToken,
      refresh_token: tokens.refreshToken,
    };
  }
}

import { Injectable, UnauthorizedException } from '@nestjs/common';
import { PassportStrategy } from '@nestjs/passport';
import { ExtractJwt, Strategy } from 'passport-jwt';
import { ConfigService } from '@nestjs/config';
import { Request } from 'express';

@Injectable()
export class AdminJwtRefreshStrategy extends PassportStrategy(
  Strategy,
  'admin-jwt-refresh',
) {
  constructor(private configService: ConfigService) {
    super({
      jwtFromRequest: ExtractJwt.fromExtractors([
        (request: Request) => {
          return request?.cookies?.admin_refresh_token as string | null;
        },
      ]),
      ignoreExpiration: false,
      secretOrKey:
        configService.get<string>('JWT_REFRESH_SECRET') ||
        'supersecretrefreshjwtsecret',
      passReqToCallback: true,
    });
  }

  validate(req: Request, payload: any) {
    const refreshToken = req.cookies?.admin_refresh_token as string;
    const sessionId = payload.sessionId as string;

    if (!refreshToken || !sessionId) {
      throw new UnauthorizedException('Refresh token or session ID missing');
    }

    return {
      ...payload,
      refreshToken,
      sessionId,
    };
  }
}

import { Test, TestingModule } from '@nestjs/testing';
import { CustomerAuthController } from './customer-auth.controller';
import { CustomerAuthService } from './customer-auth.service';
import { CustomerUsersService } from '../users/customer-users.service';
import { UnauthorizedException } from '@nestjs/common';
import type { Response, Request } from 'express';
import * as bcrypt from 'bcrypt';

jest.mock('bcrypt');

describe('CustomerAuthController', () => {
  let controller: CustomerAuthController;
  let authService: {
    validateCustomer: jest.Mock;
    login: jest.Mock;
    logout: jest.Mock;
    refreshTokens: jest.Mock;
  };
  let usersService: {
    findByEmail: jest.Mock;
    create: jest.Mock;
  };

  beforeEach(async () => {
    authService = {
      validateCustomer: jest.fn(),
      login: jest.fn(),
      logout: jest.fn().mockResolvedValue(undefined),
      refreshTokens: jest.fn(),
    };

    usersService = {
      findByEmail: jest.fn(),
      create: jest.fn(),
    };

    const module: TestingModule = await Test.createTestingModule({
      controllers: [CustomerAuthController],
      providers: [
        { provide: CustomerAuthService, useValue: authService },
        { provide: CustomerUsersService, useValue: usersService },
      ],
    }).compile();

    controller = module.get<CustomerAuthController>(CustomerAuthController);
  });

  describe('register', () => {
    it('should register a new customer', async () => {
      usersService.findByEmail.mockResolvedValue(null);
      (bcrypt.hash as jest.Mock).mockResolvedValue('hash');
      const mockCustomer = {
        id: '1',
        email: 'test@test.com',
        passwordHash: 'hash',
      };
      usersService.create.mockResolvedValue(mockCustomer);

      const result = await controller.register({
        firstName: 'Test',
        lastName: 'User',
        email: 'test@test.com',
        password: 'password',
        phone: '123',
      });

      // eslint-disable-next-line @typescript-eslint/no-unused-vars
      const { passwordHash: _, ...expectedCustomer } = mockCustomer;
      expect(result).toEqual({
        message: 'Registered successfully',
        customer: expectedCustomer,
      });
    });

    it('should throw if email in use', async () => {
      usersService.findByEmail.mockResolvedValue({ id: '1' });
      await expect(
        controller.register({
          firstName: 'Test',
          lastName: 'User',
          email: 'test@test.com',
          password: 'password',
          phone: '123',
        }),
      ).rejects.toThrow(UnauthorizedException);
    });
  });

  describe('login', () => {
    it('should login and set refresh cookie', async () => {
      const mockCustomer = { id: '1', email: 'test@test.com' };
      authService.validateCustomer.mockResolvedValue(mockCustomer);
      authService.login.mockResolvedValue({
        access_token: 'at',
        refresh_token: 'rt',
        customer: mockCustomer,
      });

      const mockRes = { cookie: jest.fn() } as unknown as Response;

      const result = await controller.login(
        { email: 'test@test.com', password: 'password' },
        mockRes,
      );

      expect(mockRes.cookie).toHaveBeenCalledWith(
        'client_refresh_token',
        'rt',
        expect.any(Object),
      );
      expect(result).toEqual({
        message: 'Logged in successfully',
        access_token: 'at',
        customer: mockCustomer,
      });
    });
  });

  describe('logout', () => {
    it('should logout and clear refresh cookie', () => {
      const mockReq = { user: { sessionId: 'sid' } } as unknown as Request;
      const mockRes = { clearCookie: jest.fn() } as unknown as Response;

      const result = controller.logout(mockReq, mockRes);

      expect(authService.logout).toHaveBeenCalledWith('sid');
      expect(mockRes.clearCookie).toHaveBeenCalledWith('client_refresh_token', {
        path: '/auth/customer',
      });
      expect(result).toEqual({ message: 'Logged out successfully' });
    });
  });
});

import {
  Controller,
  Post,
  Body,
  UseGuards,
  Request,
  Get,
  Res,
  UnauthorizedException,
} from '@nestjs/common';
import { CustomerAuthService } from './customer-auth.service';
import { CustomerUsersService } from '../users/customer-users.service';
import type { Response } from 'express';
import { CustomerJwtAuthGuard } from './guards/customer-jwt-auth.guard';
import { CustomerJwtRefreshGuard } from './guards/customer-jwt-refresh.guard';
import * as bcrypt from 'bcrypt';
import { RegisterCustomerDto } from './dto/register-customer.dto';
import { LoginCustomerDto } from './dto/login-customer.dto';

@Controller('auth/customer')
export class CustomerAuthController {
  constructor(
    private customerAuthService: CustomerAuthService,
    private customerUsersService: CustomerUsersService,
  ) {}

  @Post('register')
  async register(@Body() body: RegisterCustomerDto) {
    const existing = await this.customerUsersService.findByEmail(body.email);
    if (existing) {
      throw new UnauthorizedException('Email already in use');
    }

    const passwordHash = await bcrypt.hash(body.password, 10);
    const customer = await this.customerUsersService.create({
      firstName: body.firstName,
      lastName: body.lastName,
      email: body.email,
      phone: body.phone,
      passwordHash,
    });

    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    const { passwordHash: _, ...result } = customer;
    return {
      message: 'Registered successfully',
      customer: result,
    };
  }

  @Post('login')
  async login(
    @Body() body: LoginCustomerDto,
    @Res({ passthrough: true }) res: Response,
  ) {
    const customer = await this.customerAuthService.validateCustomer(
      body.email,
      body.password,
    );

    if (!customer) {
      throw new UnauthorizedException('Invalid credentials');
    }

    const result = await this.customerAuthService.login(customer);

    res.cookie('client_refresh_token', result.refresh_token, {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'lax',
      path: '/auth/customer',
      maxAge: 7 * 24 * 60 * 60 * 1000,
    });

    return {
      message: 'Logged in successfully',
      access_token: result.access_token,
      customer: result.customer,
    };
  }

  @UseGuards(CustomerJwtAuthGuard)
  @Post('logout')
  logout(@Request() req: any, @Res({ passthrough: true }) res: Response) {
    const sessionId = req.user.sessionId;
    this.customerAuthService.logout(sessionId);

    res.clearCookie('client_refresh_token', { path: '/auth/customer' });

    return { message: 'Logged out successfully' };
  }

  @UseGuards(CustomerJwtAuthGuard)
  @Get('me')
  getProfile(@Request() req: any) {
    return req.user;
  }

  @UseGuards(CustomerJwtRefreshGuard)
  @Post('refresh')
  async refresh(
    @Request() req: any,
    @Res({ passthrough: true }) res: Response,
  ) {
    const customerId = req.user.sub;
    const refreshToken = req.user.refreshToken;
    const sessionId = req.user.sessionId;

    const tokens = await this.customerAuthService.refreshTokens(
      customerId,
      refreshToken,
      sessionId,
    );

    if (!tokens) {
      res.clearCookie('client_refresh_token', { path: '/auth/customer' });
      throw new UnauthorizedException('Invalid refresh token');
    }

    res.cookie('client_refresh_token', tokens.refresh_token, {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'lax',
      path: '/auth/customer',
      maxAge: 7 * 24 * 60 * 60 * 1000,
    });

    return {
      message: 'Tokens refreshed successfully',
      access_token: tokens.access_token,
    };
  }
}

import { Module } from '@nestjs/common';
import { CustomerAuthService } from './customer-auth.service';
import { CustomerAuthController } from './customer-auth.controller';
import { CustomerUsersModule } from '../users/customer-users.module';
import { PassportModule } from '@nestjs/passport';
import { JwtModule } from '@nestjs/jwt';
import { ConfigModule, ConfigService } from '@nestjs/config';
import { CustomerJwtStrategy } from './strategies/customer-jwt.strategy';
import { CustomerJwtRefreshStrategy } from './strategies/customer-jwt-refresh.strategy';

@Module({
  imports: [
    CustomerUsersModule,
    PassportModule,
    JwtModule.registerAsync({
      imports: [ConfigModule],
      useFactory: async (configService: ConfigService) => ({
        secret: configService.get<string>('JWT_SECRET') || 'super-secret',
        signOptions: { expiresIn: '15m' },
      }),
      inject: [ConfigService],
    }),
  ],
  controllers: [CustomerAuthController],
  providers: [
    CustomerAuthService,
    CustomerJwtStrategy,
    CustomerJwtRefreshStrategy,
  ],
})
export class CustomerAuthModule {}

