  let customerUsersService: { findByEmail: jest.Mock; findById: jest.Mock };
  let prismaService: {
    customerSession: {
      create: jest.Mock;
      update: jest.Mock;
      delete: jest.Mock;
      findUnique: jest.Mock;
    };
    customer: { update: jest.Mock };
