      customerUsersService.findByEmail.mockResolvedValue(null);
      expect(
        await service.validateCustomer('customer@test.com', 'password'),
      ).toBeNull();
    });

    it('should return customer without passwordHash if valid', async () => {
      customerUsersService.findByEmail.mockResolvedValue(mockCustomer);
      (bcrypt.compare as jest.Mock).mockResolvedValue(true);
      const result = await service.validateCustomer(
        'customer@test.com',
        'password',
      );
      // eslint-disable-next-line @typescript-eslint/no-unused-vars
      const { passwordHash, ...expected } = mockCustomer;
      expect(result).toEqual(expected);
    });
  });

  describe('login', () => {
    it('should create session and return tokens', async () => {
      (bcrypt.hash as jest.Mock).mockResolvedValue('hashed-refresh-token');
      const result = await service.login(mockCustomer);

      expect(prismaService.customerSession.create).toHaveBeenCalled();
      expect(prismaService.customer.update).toHaveBeenCalled();
      expect(result).toEqual({
        access_token: 'mock-jwt-token',
        refresh_token: 'mock-jwt-token',
        customer: mockCustomer,
      });
    });
  });
});

import { Injectable, UnauthorizedException } from '@nestjs/common';
import { CustomerUsersService } from '../users/customer-users.service';
import { PrismaService } from '../../shared/prisma/prisma.service';
import { JwtService } from '@nestjs/jwt';
import { ConfigService } from '@nestjs/config';
import * as bcrypt from 'bcrypt';
import { randomUUID } from 'crypto';

@Injectable()
export class CustomerAuthService {
  constructor(
    private customerUsersService: CustomerUsersService,
    private prisma: PrismaService,
    private jwtService: JwtService,
    private configService: ConfigService,
  ) {}

  async validateCustomer(email: string, pass: string): Promise<any> {
    const customer = await this.customerUsersService.findByEmail(email);
    if (customer && customer.isActive) {
      const isMatch = await bcrypt.compare(pass, customer.passwordHash);
      if (isMatch) {
        // eslint-disable-next-line @typescript-eslint/no-unused-vars
        const { passwordHash, ...result } = customer;
        return result;
      }
    }
    return null;
  }

  async login(customer: any) {
    const sessionId = randomUUID();
    const tokens = await this.getTokens(customer.id, customer.email, sessionId);
    const hashedToken = await bcrypt.hash(tokens.refreshToken, 10);

    const expiresAt = new Date();
    expiresAt.setDate(expiresAt.getDate() + 7); // 7 days

    await this.prisma.customerSession.create({
      data: {
        id: sessionId,
        customerId: customer.id,
        hashedToken,
        expiresAt,
      },
    });

    await this.prisma.customer.update({
      where: { id: customer.id },
      data: { lastLogin: new Date() },
    });

    return {
      access_token: tokens.accessToken,
      refresh_token: tokens.refreshToken,
      customer,
    };
  }

  async logout(sessionId: string) {
    try {
      await this.prisma.customerSession.delete({
        where: { id: sessionId },
      });
    } catch (e) {
      // Ignore if session already deleted or doesn't exist
    }
  }

  async refreshTokens(
    customerId: string,
    refreshToken: string,
    sessionId: string,
  ) {
    const session = await this.prisma.customerSession.findUnique({
      where: { id: sessionId },
    });

    if (!session || !session.hashedToken) return null;

    if (session.expiresAt < new Date()) {
      await this.prisma.customerSession.delete({ where: { id: sessionId } });
      return null;
    }

    const rtMatches = await bcrypt.compare(refreshToken, session.hashedToken);
    if (!rtMatches) return null;

    const customer = await this.customerUsersService.findById(customerId);
    if (!customer) return null;

    const tokens = await this.getTokens(customer.id, customer.email, sessionId);
    const newHashedToken = await bcrypt.hash(tokens.refreshToken, 10);

    const expiresAt = new Date();
    expiresAt.setDate(expiresAt.getDate() + 7);

    await this.prisma.customerSession.update({
      where: { id: sessionId },
      data: {
        hashedToken: newHashedToken,
        expiresAt,
      },
    });

    return {
      access_token: tokens.accessToken,
      refresh_token: tokens.refreshToken,
    };
  }

  async getTokens(customerId: string, email: string, sessionId: string) {
    const jwtPayload = {
      sub: customerId,
      email,
      sessionId,
    };

    const [accessToken, refreshToken] = await Promise.all([
      this.jwtService.signAsync(jwtPayload, {
        secret: this.configService.get<string>('JWT_SECRET') || 'super-secret',
        expiresIn: '15m',
      }),
      this.jwtService.signAsync(jwtPayload, {
        secret:
          this.configService.get<string>('JWT_REFRESH_SECRET') ||
          'super-refresh-secret',
        expiresIn: '7d',
      }),
    ]);

    return {
      accessToken,
      refreshToken,
    };
  }
}

import { Injectable, UnauthorizedException } from '@nestjs/common';
import { PassportStrategy } from '@nestjs/passport';
import { ExtractJwt, Strategy } from 'passport-jwt';
import { ConfigService } from '@nestjs/config';
import { Request } from 'express';

@Injectable()
export class CustomerJwtRefreshStrategy extends PassportStrategy(
  Strategy,
  'customer-jwt-refresh',
) {
  constructor(private configService: ConfigService) {
    super({
      jwtFromRequest: ExtractJwt.fromExtractors([
        (request: Request) => {
          return request?.cookies?.client_refresh_token;
        },
      ]),
      ignoreExpiration: false,
      secretOrKey:
        configService.get<string>('JWT_REFRESH_SECRET') ||
        'super-refresh-secret',
      passReqToCallback: true,
    });
  }

  async validate(request: Request, payload: any) {
    const refreshToken = request?.cookies?.client_refresh_token;

    if (!refreshToken) {
      throw new UnauthorizedException();
    }

    return {
      ...payload,
      refreshToken,
      sessionId: payload.sessionId,
    };
  }
}

import { Injectable, UnauthorizedException } from '@nestjs/common';
import { PassportStrategy } from '@nestjs/passport';
import { ExtractJwt, Strategy } from 'passport-jwt';
import { ConfigService } from '@nestjs/config';
import { CustomerUsersService } from '../../users/customer-users.service';

@Injectable()
export class CustomerJwtStrategy extends PassportStrategy(
  Strategy,
  'customer-jwt',
) {
  constructor(
    private configService: ConfigService,
    private usersService: CustomerUsersService,
  ) {
    super({
      jwtFromRequest: ExtractJwt.fromAuthHeaderAsBearerToken(),
      ignoreExpiration: false,
      secretOrKey: configService.get<string>('JWT_SECRET') || 'super-secret',
    });
  }

  async validate(payload: any) {
    // payload should have { sub, email, sessionId }
    const customer = await this.usersService.findById(payload.sub);
    if (!customer) {
      throw new UnauthorizedException();
    }

    // We attach sessionId so that the controller can use it for logout if needed
    return {
      id: customer.id,
      email: customer.email,
      firstName: customer.firstName,
      lastName: customer.lastName,
      sessionId: payload.sessionId,
    };
  }
}

import { NestFactory } from '@nestjs/core';
import { AppModule } from './app.module';
import cookieParser from 'cookie-parser';
import { ConfigService } from '@nestjs/config';
import { setupSwagger } from './shared/utils/setup-swagger';
import { ValidationPipe } from '@nestjs/common';
import { GlobalExceptionFilter } from './shared/filters/global-exception.filter';
import { TransformInterceptor } from './shared/interceptors/transform.interceptor';

async function bootstrap() {
  const app = await NestFactory.create(AppModule);

  app.useGlobalPipes(
    new ValidationPipe({
      whitelist: true,
      forbidNonWhitelisted: true,
      transform: true,
    }),
  );

  app.useGlobalFilters(new GlobalExceptionFilter());
  app.useGlobalInterceptors(new TransformInterceptor());

  const configService = app.get(ConfigService);

  app.use(cookieParser());

  app.enableCors({
    origin:
      configService.get<string>('NEXT_PUBLIC_API_URL') ||
      'http://localhost:3000',
    credentials: true,
  });

  setupSwagger(app);

  const port = configService.get<number>('PORT') ?? 3001;

  await app.listen(port);

  console.log(`🚀 Application is running on: http://localhost:${port}`);

  if (configService.get<string>('NODE_ENV') !== 'production') {
    console.log(
      `📚 Documentation is available at: http://localhost:${port}/api/docs`,
    );
  }
}

bootstrap();

