    });
  });
});

import {
  ExceptionFilter,
  Catch,
  ArgumentsHost,
  HttpException,
  HttpStatus,
  Logger,
} from '@nestjs/common';
import { Request, Response } from 'express';

@Catch()
export class GlobalExceptionFilter implements ExceptionFilter {
  private readonly logger = new Logger(GlobalExceptionFilter.name);

  catch(exception: unknown, host: ArgumentsHost) {
    const ctx = host.switchToHttp();
    const response = ctx.getResponse<Response>();
    const request = ctx.getRequest<Request>();

    let status = HttpStatus.INTERNAL_SERVER_ERROR;
    let message: string | object = 'Internal server error';

    if (exception instanceof HttpException) {
      status = exception.getStatus();
      const exceptionResponse = exception.getResponse();

      // If the response is an object (like validation errors), use it directly,
      // otherwise use the string message.
      message =
        typeof exceptionResponse === 'object' && exceptionResponse !== null
          ? (exceptionResponse as any).message || exceptionResponse
          : exceptionResponse;
    } else if (exception instanceof Error) {
      // Log unhandled non-HTTP errors with stack trace for debugging
      this.logger.error(
        `Unhandled Exception: ${exception.message}`,
        exception.stack,
      );
      message = exception.message;
    }

    // Always log the error
    this.logger.error(
      `${request.method} ${request.url} [${status}]: ${JSON.stringify(message)}`,
    );

    response.status(status).json({
      success: false,
      error: {
        statusCode: status,
        message,
        path: request.url,
      },
      timestamp: new Date().toISOString(),
    });
  }
}

import {
  Injectable,
  NestInterceptor,
  ExecutionContext,
  CallHandler,
} from '@nestjs/common';
import { Observable } from 'rxjs';
import { map } from 'rxjs/operators';

export interface Response<T> {
  success: boolean;
  data: T;
  message?: string;
}

@Injectable()
export class TransformInterceptor<T> implements NestInterceptor<
  T,
  Response<T>
> {
  intercept(
    context: ExecutionContext,
    next: CallHandler,
  ): Observable<Response<T>> {
    return next.handle().pipe(
      map((data) => {
        // If the controller already returned a structure with a message, extract it
        let message = undefined;
        let responseData = data;

        if (data && typeof data === 'object' && 'message' in data) {
          message = data.message;
          // Create a shallow copy without the message property for the data payload
          // eslint-disable-next-line @typescript-eslint/no-unused-vars
          const { message: _, ...rest } = data;

          // If the only property was message, data becomes empty object,
          // or we can just use the rest of the object
          responseData = Object.keys(rest).length > 0 ? rest : undefined;
        }

        return {
          success: true,
          message,
          data: responseData,
        };
      }),
    );
  }
}
